    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function comparison() {
    const left = sum();
    if (!comparisonOperators.has(current().value)) return left;
    const operands = [left];
    const operators = [];
    while (comparisonOperators.has(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

