    let left = unary();
    while (productOperators.has(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return power();
  }

  function power() {
    const left = primary();
    if (is('**')) {
