        frames.pop();
      }
    } else if (node.type === 'binary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.left, phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.phase = 2;
        frames.push({ node: node.right, phase: 0 });
      } else {
        result = apply(node.operator, frame.left, result);
        frames.pop();
      }
    } else if (node.type === 'comparison') {
