'use strict';
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { evaluate, ExprError } = require('./src');

const cases = [
  ['-2 ** 2', -4], ['(-2) ** 2', 4], ['2 ** -1', 0.5],
  ['2 ** 3 ** 2', 512], ['2 ** -2 ** 2', 0.0625],
  ['--2 ** 2', 4], ['3 * -2 ** 2', -12], ['-2 ** 2 * 3', -12],
  ['8 / 4 / 2', 1], ['8 - 4 - 2', 2], ['2 + 3 * 4', 14],
  ['.5 + 5. + 1.5e-3 + 2E+1', 25.5015],
  ['-7 // 2', -4], ['7 // -2', -4], ['-7 // -2', 3],
  ['-7 % 3', 2], ['7 % -3', -2], ['-7 % -3', -1],
  ['-5.5 // 2', -3], ['-5.5 % 2', 0.5], ['5.5 % -2', -0.5],
  ['3 < 2 < missing', false], ['1 < 2 <= 2', true],
  ['3 > 2 > 1', true], ['1 == 1 != 2', true], ['2 >= 2 > 1', true],
  ['1 < 2 > 3', false], ['(1 < 2) + 3', 4], ['(1 > 2) * 8', 0],
  ['(1 < 2) == 1', true], ['(1 > 2) == 0', true],
  ['1 == (2 > 1)', true], ['1 + 1 < 2 * 2', true],
  ['min(3, 2, 1)', 1], ['max(1, 3, 2)', 3], ['abs(-3)', 3],
  ['max(min(4, 2), abs(-3))', 3], ['min(1 < 2, 4)', 1],
];
for (const [source, expected] of cases) assert.equal(evaluate(source), expected, source);
for (const source of ['-6 % 3', '6 % -3', '0 // -3', '-0 // 3', '-0 % 3']) {
  assert.equal(Object.is(evaluate(source), 0), true, source);
}
for (let a = -12; a <= 12; a++) {
  for (let b = -5; b <= 5; b++) {
    if (!b) continue;
    const q = evaluate('a // b', { a, b });
    const r = evaluate('a % b', { a, b });
    assert.equal(q, Math.floor(a / b) || 0);
    assert.equal(q * b + r, a);
    assert.ok(r === 0 || Math.sign(r) === Math.sign(b));
    assert.ok(Math.abs(r) < Math.abs(b));
  }
}

function errorAt(source, column, variables) {
  assert.throws(() => evaluate(source, variables), e => e instanceof ExprError && e.column === column, source);
}
for (const [source, column] of [
  ['  missing', 3], ['1 +   missing', 7], ['1 /   0', 3],
  ['1  // 0', 4], ['1   % -0', 5], ['  @', 3], ['1 +  😀', 6],
  ['', 1], ['   ', 4], ['1 +   ', 7], ['(1  ', 5],
  ['1  2', 4], ['1 = 2', 3], ['1 ! 2', 3], ['1.2.3', 4],
  ['1e+', 2], ['2(3)', 2], ['min(1,)', 7], ['min(,1)', 5],
  ['  foo(1)', 3], ['  abs()', 3], ['  abs(1,2)', 3], ['  min()', 3],
  ['1 < 2 <', 8], ['  constructor', 3],
]) errorAt(source, column);

let reads = [];
let count = 0;
const variables = Object.create({ inherited: 1 });
Object.defineProperties(variables, {
  a: { get() { reads.push('a'); return 1; } },
  b: { get() { reads.push('b'); return 2; } },
  c: { get() { reads.push('c'); return 3; } },
  changing: { get() { return ++count; } },
});
assert.equal(evaluate('a < b < c', variables), true);
assert.deepEqual(reads, ['a', 'b', 'c']);
reads = [];
assert.equal(evaluate('a > b < c', variables), false);
assert.deepEqual(reads, ['a', 'b']);
reads = [];
assert.equal(evaluate('max(a, b, c) + a', variables), 4);
assert.deepEqual(reads, ['a', 'b', 'c', 'a']);
assert.equal(evaluate('changing + changing', variables), 3);
assert.equal(count, 2);
assert.equal(evaluate('0 < changing < 4', variables), true);
assert.equal(count, 3);
errorAt('inherited', 1, variables);
assert.equal(evaluate('a', Object.freeze({ a: 7 })), 7);
reads = [];
errorAt('a + abs()', 5, variables);
errorAt('a > b < nope()', 9, variables);
errorAt('a > b < (1 + )', 13, variables);
assert.deepEqual(reads, []);
assert.equal(evaluate('a > b < (1 / 0)', variables), false);
assert.equal(evaluate('x < x <= missing', { x: NaN }), false);

const operands = 120001;
for (const [name, source, expected] of [
  ['sum', Array(operands).fill('1').join('+'), operands],
  ['product', Array(operands).fill('1').join('*'), 1],
  ['comparison', Array(operands).fill('1').join('<='), true],
]) {
  const start = performance.now();
  assert.equal(evaluate(source), expected);
  const elapsed = performance.now() - start;
  assert.ok(elapsed < 1000, `${name}: ${elapsed.toFixed(1)}ms`);
  console.log(`${name}: ${operands} operands, ${elapsed.toFixed(1)}ms`);
}
console.log('Contract checks passed');

