const { evaluate, ExprError } = require('./src');

const cases = [
  ['-2 ** 2', -4], ['(-2) ** 2', 4], ['2 ** -1', 0.5],
  ['2 ** 3 ** 2', 512], ['2 ** -2 ** 2', 0.0625],
  ['--2 ** 2', 4], ['3 * -2 ** 2', -12], ['-2 ** 2 * 3', -12],
  ['8 / 4 / 2', 1], ['8 - 4 - 2', 2], ['2 + 3 * 4', 14],
  ['.5 + 5. + 1.5e-3 + 2E+1', 25.5015],
  ['-7 // 2', -4], ['7 // -2', -4], ['-7 // -2', 3],
  ['-7 % 3', 2], ['7 % -3', -2], ['-7 % -3', -1],
  ['-5.5 // 2', -3], ['-5.5 % 2', 0.5], ['5.5 % -2', -0.5],
  ['3 < 2 < missing', false], ['1 < 2 <= 2', true],
  ['3 > 2 > 1', true], ['1 == 1 != 2', true], ['2 >= 2 > 1', true],
  ['1 < 2 > 3', false], ['(1 < 2) + 3', 4], ['(1 > 2) * 8', 0],
  ['(1 < 2) == 1', true], ['(1 > 2) == 0', true],
  ['1 == (2 > 1)', true], ['1 + 1 < 2 * 2', true],
  ['min(3, 2, 1)', 1], ['max(1, 3, 2)', 3], ['abs(-3)', 3],
  ['max(min(4, 2), abs(-3))', 3], ['min(1 < 2, 4)', 1],
];
for (const [source, expected] of cases) assert.equal(evaluate(source), expected, source);
for (const source of ['-6 % 3', '6 % -3', '0 // -3', '-0 // 3', '-0 % 3']) {
  assert.equal(Object.is(evaluate(source), 0), true, source);
}
for (let a = -12; a <= 12; a++) {
  for (let b = -5; b <= 5; b++) {
    if (!b) continue;
    const q = evaluate('a // b', { a, b });
    const r = evaluate('a % b', { a, b });
    assert.equal(q, Math.floor(a / b) || 0);
    assert.equal(q * b + r, a);
    assert.ok(r === 0 || Math.sign(r) === Math.sign(b));
    assert.ok(Math.abs(r) < Math.abs(b));
  }
}

function errorAt(source, column, variables) {
  assert.throws(() => evaluate(source, variables), e => e instanceof ExprError && e.column === column, source);
}
